def rich_text_to_md(r):
    o=[]
    for it in r or []:
        s=it.get('plain_text','')
        a=it.get('annotations') or {}
        if a.get('code'): s=f'`{s}`'
        if a.get('italic'): s=f'*{s}*'
        if a.get('bold'): s=f'**{s}**'
        o.append(s)
    return ''.join(o)

def block_to_md(b):
    t=b.get('type','')
    p=b.get(t) or {}
    txt=rich_text_to_md(p.get('rich_text',[]))
    m={'heading_1':'# ','heading_2':'## ','heading_3':'### ','bulleted_list_item':'- ','numbered_list_item':'1. ','quote':'> '}
    if t in m: return (m[t]+txt).strip()
    if t=='divider': return '---'
    return txt

